//! Acceptance of the natural bond orbital analysis (`natural-bond`).
//!
//! Oracles: frozen external natural atomic orbital populations
//! (`tests/oracle_data/nbo_oracle.json`, generated by
//! `tools/oracle/gen_nbo.py` for Hartree-Fock references of molecules whose
//! natural minimal basis is the same in both programs): natural charges,
//! natural spin populations, sorted NAO occupancies per atom and Wiberg
//! indices. Independent recomputations in the test: the second-order
//! donor-acceptor energies from the SCF Fock matrix and the returned NBOs,
//! the occupied density from the NLMOs, the AO metric of the NBOs.
//! Physical limits: the configuration and Lewis structure of the neon atom,
//! the unit bond index of H2 in a minimal basis, the spin-resolved analysis
//! of a closed shell (half the spin-summed occupancies and energies), the
//! one-hole Lewis structure of the water cation, invariance under a
//! rotation of the molecule and the known Lewis structures of water,
//! formaldehyde and ethylene. The first run found the empty Rydberg NBOs
//! (an exactly degenerate space) oriented with the molecule, so that their
//! Fock energies changed by up to 0.91 Hartree under a rotation; degenerate
//! spaces are now fixed by the Fock matrix.

use dft_rs::driver::method::{prepare_molecular, run_molecular_reference, MolecularMethod};
use dft_rs::driver::{run, Controls, System, Value};
use dft_rs::properties::natural_bond::{
    natural_bond_analysis, NaturalBondAnalysis, NboKind, NboOptions, NboSpin,
};
use dft_rs::Matrix;

const WATER: [(u8, [f64; 3]); 3] = [
    (8, [0.0, 0.0, 0.23]),
    (1, [0.0, 1.4309, -0.8867]),
    (1, [0.12, -1.4809, -0.9067]),
];
const FORMALDEHYDE: [(u8, [f64; 3]); 4] = [
    (6, [0.0, 0.0, -1.0]),
    (8, [0.0, 0.0, 1.28]),
    (1, [0.0, 1.78, -2.1]),
    (1, [0.05, -1.77, -2.1]),
];
const ETHYLENE: [(u8, [f64; 3]); 6] = [
    (6, [0.0, 0.0, 1.26]),
    (6, [0.0, 0.0, -1.26]),
    (1, [0.0, 1.75, 2.33]),
    (1, [0.0, -1.75, 2.33]),
    (1, [0.0, 1.75, -2.33]),
    (1, [0.0, -1.75, -2.33]),
];

fn system(atoms: &[(u8, [f64; 3])]) -> System {
    System::molecule(
        atoms.iter().map(|(z, _)| *z).collect(),
        atoms.iter().map(|(_, r)| *r).collect(),
    )
}

fn controls(basis: &str, charge: i64, multiplicity: i64, extra: &[(&str, Value)]) -> Controls {
    let mut pairs = vec![
        ("xc".to_string(), Value::Str("hf".into())),
        ("basis".to_string(), Value::Str(basis.into())),
        ("charge".to_string(), Value::Int(charge)),
        ("multiplicity".to_string(), Value::Int(multiplicity)),
        ("conv_tol".to_string(), Value::Float(1e-12)),
        ("conv_tol_grad".to_string(), Value::Float(1e-9)),
    ];
    for (k, v) in extra {
        pairs.push((k.to_string(), v.clone()));
    }
    Controls::from_value(&Value::Object(pairs)).unwrap()
}

/// Library analysis with the SCF reference, for the independent checks.
fn analyse(
    atoms: &[(u8, [f64; 3])],
    basis: &str,
    charge: i64,
    multiplicity: i64,
    spin: NboSpin,
) -> (NaturalBondAnalysis, dft_rs::ScfResult) {
    let method =
        MolecularMethod::from_controls(&controls(basis, charge, multiplicity, &[])).unwrap();
    let s = system(atoms);
    let setup = prepare_molecular(&s.numbers, &s.positions, &method).unwrap();
    let reference = run_molecular_reference(&setup).unwrap();
    assert!(reference.scf.converged);
    let analysis = natural_bond_analysis(
        &setup.molecule,
        &setup.basis,
        &reference.scf,
        spin,
        &NboOptions::default(),
    )
    .unwrap();
    (analysis, reference.scf)
}

fn floats(v: &Value) -> Vec<f64> {
    v.numeric_array().unwrap().1
}

fn largest_difference(a: &[f64], b: &[f64]) -> f64 {
    assert_eq!(a.len(), b.len());
    a.iter()
        .zip(b)
        .fold(0.0_f64, |m, (x, y)| m.max((x - y).abs()))
}

#[test]
fn natural_populations_match_the_frozen_oracle() {
    let data = Value::parse_json(include_str!("oracle_data/nbo_oracle.json")).unwrap();
    let cases = data.get("cases").and_then(Value::as_array).unwrap();
    assert_eq!(cases.len(), 7);
    let mut worst = [0.0_f64; 5];
    for case in cases {
        let text = |key: &str| case.get(key).and_then(Value::as_str).unwrap().to_string();
        let int = |key: &str| case.get(key).and_then(Value::as_i64).unwrap();
        let numbers: Vec<u8> = floats(case.get("numbers").unwrap())
            .iter()
            .map(|z| *z as u8)
            .collect();
        let positions: Vec<[f64; 3]> = floats(case.get("positions").unwrap())
            .chunks(3)
            .map(|r| [r[0], r[1], r[2]])
            .collect();
        let report = run(
            "natural-bond",
            &System::molecule(numbers.clone(), positions),
            &controls(&text("basis"), int("charge"), int("multiplicity"), &[]),
        )
        .unwrap();
        let energy = (report.get("energy").and_then(Value::as_f64).unwrap()
            - case.get("energy").and_then(Value::as_f64).unwrap())
        .abs();
        let charges = largest_difference(
            &floats(report.get("natural_charges").unwrap()),
            &floats(case.get("natural_charges").unwrap()),
        );
        let spins = largest_difference(
            &floats(report.get("natural_spin_populations").unwrap()),
            &floats(case.get("natural_spin_populations").unwrap()),
        );
        let wiberg = largest_difference(
            &floats(report.get("wiberg_bond_indices").unwrap()),
            &floats(case.get("wiberg_bond_indices").unwrap()),
        );
        // Sorted NAO occupancies per atom.
        let occupancies = floats(report.get("nao_occupancies").unwrap());
        let owners = floats(report.get("nao_atoms").unwrap());
        let expected = case
            .get("atom_occupancies")
            .and_then(Value::as_array)
            .unwrap();
        let mut orbitals = 0.0_f64;
        for (atom, list) in expected.iter().enumerate() {
            let mut mine: Vec<f64> = occupancies
                .iter()
                .zip(&owners)
                .filter(|(_, a)| **a as usize == atom)
                .map(|(o, _)| *o)
                .collect();
            mine.sort_by(|a, b| b.total_cmp(a));
            orbitals = orbitals.max(largest_difference(&mine, &floats(list)));
        }
        println!(
            "{} {} multiplicity {}: energy {energy:.3e}, natural charges {charges:.3e}, spin \
             populations {spins:.3e}, NAO occupancies {orbitals:.3e}, Wiberg {wiberg:.3e}",
            text("molecule"),
            text("basis"),
            int("multiplicity")
        );
        for (w, v) in worst
            .iter_mut()
            .zip([energy, charges, spins, orbitals, wiberg])
        {
            *w = w.max(v);
        }
    }
    println!("largest deviations [energy, charges, spins, occupancies, Wiberg] {worst:?}");
    assert!(worst[0] < 1e-8);
    assert!(worst[1] < 1e-6 && worst[2] < 1e-6 && worst[3] < 1e-6 && worst[4] < 1e-6);
}

fn lewis_labels(analysis: &NaturalBondAnalysis, channel: usize) -> Vec<String> {
    analysis.channels[channel]
        .nbos
        .iter()
        .filter(|b| b.kind.is_lewis())
        .map(|b| b.label.clone())
        .collect()
}

#[test]
fn closed_shell_lewis_structures_and_orbital_checks() {
    for (name, atoms, expected) in [
        (
            "water",
            &WATER[..],
            vec![
                "CR(1) O1",
                "LP(1) O1",
                "LP(2) O1",
                "BD(1) O1-H2",
                "BD(1) O1-H3",
            ],
        ),
        (
            "formaldehyde",
            &FORMALDEHYDE[..],
            vec![
                "CR(1) C1",
                "CR(1) O2",
                "LP(1) O2",
                "LP(2) O2",
                "BD(1) C1-O2",
                "BD(2) C1-O2",
                "BD(1) C1-H3",
                "BD(1) C1-H4",
            ],
        ),
        (
            "ethylene",
            &ETHYLENE[..],
            vec![
                "CR(1) C1",
                "CR(1) C2",
                "BD(1) C1-C2",
                "BD(2) C1-C2",
                "BD(1) C1-H3",
                "BD(1) C1-H4",
                "BD(1) C2-H5",
                "BD(1) C2-H6",
            ],
        ),
    ] {
        let (analysis, scf) = analyse(atoms, "6-31g*", 0, 1, NboSpin::Auto);
        assert_eq!(analysis.channels.len(), 1);
        let channel = &analysis.channels[0];
        let mut labels = lewis_labels(&analysis, 0);
        let mut wanted: Vec<String> = expected.iter().map(|s| s.to_string()).collect();
        labels.sort();
        wanted.sort();
        let electrons = 2.0 * scf.n_alpha as f64;
        // AO metric of the NBOs.
        let ao = analysis.nao.nao_coefficients.matmul(&channel.coefficients);
        let metric = ao.transpose_matmul(&scf.overlap.matmul(&ao));
        let metric_defect = metric.max_abs_diff(&Matrix::identity(metric.rows));
        let total: f64 = channel.nbos.iter().map(|b| b.occupancy).sum();
        // NLMOs reproduce the density: sum_i q_i |i><i| = D (NAO basis).
        let n = analysis.nao.density_nao.rows;
        let mut rebuilt = Matrix::zeros(n, n);
        for (k, nlmo) in channel.nlmos.iter().enumerate() {
            for i in 0..n {
                for j in 0..n {
                    rebuilt[(i, j)] += nlmo.occupancy
                        * channel.nlmo_coefficients[(i, k)]
                        * channel.nlmo_coefficients[(j, k)];
                }
            }
        }
        let density_defect = rebuilt.max_abs_diff(&analysis.nao.density_nao);
        println!(
            "{name}: Lewis {labels:?}, non-Lewis {:.6} of {electrons} electrons (threshold {:.2}), \
             NBO metric {metric_defect:.3e}, occupancy sum {:.3e}, NLMO density {density_defect:.3e}, \
             NLMO residual {:.3e} after {} sweeps",
            channel.non_lewis_occupancy,
            channel.lewis_threshold,
            total - electrons,
            channel.nlmo_residual,
            channel.nlmo_sweeps
        );
        for nlmo in &channel.nlmos {
            println!(
                "  NLMO of {}: occupancy {:.10}, parent {:.4}%",
                channel.nbos[nlmo.parent].label, nlmo.occupancy, nlmo.parent_percentage
            );
        }
        assert_eq!(labels, wanted);
        assert!(channel.non_lewis_occupancy < 0.02 * electrons);
        assert!(metric_defect < 1e-10);
        assert!((total - electrons).abs() < 1e-9);
        assert!(density_defect < 1e-9);
        assert!(channel
            .nlmos
            .iter()
            .all(|m| (m.occupancy - 2.0).abs() < 1e-9));
        if name == "ethylene" {
            // One C-C bond is the pi bond (pure p hybrids), the other the
            // sigma bond. The serial follows the occupancy: the first run
            // assumed BD(2) to be the pi bond and found 63.07 % p (the sigma
            // bond).
            let characters: Vec<f64> = channel
                .nbos
                .iter()
                .filter(|b| b.kind == NboKind::Bond && b.atoms == [0, 1])
                .map(|b| {
                    b.hybrids
                        .iter()
                        .map(|h| h.composition[1])
                        .fold(100.0_f64, f64::min)
                })
                .collect();
            println!("  C-C bonds: smallest p character of their hybrids {characters:?} %");
            assert_eq!(characters.len(), 2);
            assert!(characters.iter().any(|&p| p > 99.0));
            assert!(characters.iter().any(|&p| p < 75.0));
        }
    }
}

#[test]
fn donor_acceptor_energies_follow_the_fock_matrix() {
    let (analysis, scf) = analyse(&FORMALDEHYDE, "6-31g*", 0, 1, NboSpin::Auto);
    let channel = &analysis.channels[0];
    let t = &analysis.nao.nao_coefficients;
    let b = t.matmul(&channel.coefficients);
    let fock = b.transpose_matmul(&scf.fock[0].matmul(&b));
    let density = {
        let mut p = scf.density[0].clone();
        for (x, y) in p.as_mut_slice().iter_mut().zip(scf.density[1].as_slice()) {
            *x += y;
        }
        let sb = scf.overlap.matmul(&b);
        sb.transpose_matmul(&p.matmul(&sb))
    };
    let lewis: Vec<usize> = (0..channel.nbos.len())
        .filter(|&i| channel.nbos[i].kind.is_lewis())
        .collect();
    let non_lewis: Vec<usize> = (0..channel.nbos.len())
        .filter(|&i| !channel.nbos[i].kind.is_lewis())
        .collect();
    let mut total = 0.0;
    for &i in &lewis {
        for &j in &non_lewis {
            let gap = fock[(j, j)] - fock[(i, i)];
            if gap > 0.0 {
                total += density[(i, i)] * fock[(i, j)].powi(2) / gap;
            }
        }
    }
    let mut defect = (total - channel.perturbation_total.unwrap()).abs();
    for pair in &channel.perturbation {
        let (i, j) = (pair.donor, pair.acceptor);
        let independent = density[(i, i)] * fock[(i, j)].powi(2) / (fock[(j, j)] - fock[(i, i)]);
        defect = defect.max((independent - pair.stabilization).abs());
    }
    let top = channel.perturbation[0];
    println!(
        "formaldehyde: {} donor-acceptor pairs above 0.5 kcal/mol, total {:.8} Hartree, \
         largest {} -> {} {:.6} Hartree, independent recomputation defect {defect:.3e}",
        channel.perturbation.len(),
        total,
        channel.nbos[top.donor].label,
        channel.nbos[top.acceptor].label,
        top.stabilization
    );
    for pair in channel.perturbation.iter().take(6) {
        println!(
            "  {} -> {}: {:.6} Hartree (F_ij {:.6}, gap {:.6})",
            channel.nbos[pair.donor].label,
            channel.nbos[pair.acceptor].label,
            pair.stabilization,
            pair.fock_element,
            pair.energy_gap
        );
    }
    assert!(defect < 1e-12);
    // Negative hyperconjugation of the oxygen lone pair into the C-H
    // antibonds dominates.
    assert_eq!(channel.nbos[top.donor].kind, NboKind::LonePair);
    assert_eq!(channel.nbos[top.acceptor].kind, NboKind::Antibond);
    assert!(channel.nbos[top.acceptor].label.contains("H"));
}

#[test]
fn spin_resolved_analysis_of_closed_and_open_shells() {
    // Formaldehyde: its largest donor-acceptor pair stays above the
    // reporting threshold when halved (in water the first run found two
    // pairs above 0.5 kcal/mol and none at half their size).
    let (total, _) = analyse(&FORMALDEHYDE, "6-31g*", 0, 1, NboSpin::Total);
    let (separate, _) = analyse(&FORMALDEHYDE, "6-31g*", 0, 1, NboSpin::Separate);
    assert_eq!(separate.channels.len(), 2);
    let whole = &total.channels[0];
    let mut defect = 0.0_f64;
    for half in &separate.channels {
        assert_eq!(half.nbos.len(), whole.nbos.len());
        for (a, b) in half.nbos.iter().zip(&whole.nbos) {
            assert_eq!(a.label, b.label);
            defect = defect.max((a.occupancy - 0.5 * b.occupancy).abs());
            defect = defect.max((a.energy.unwrap() - b.energy.unwrap()).abs());
        }
        println!(
            "{} channel: {} pairs, total {:?}; spin-summed {} pairs, total {:?}",
            half.spin,
            half.perturbation.len(),
            half.perturbation_total,
            whole.perturbation.len(),
            whole.perturbation_total
        );
        // Halved stabilizations: fewer pairs pass the fixed reporting
        // threshold, the largest one is the same pair.
        let (h, w) = (half.perturbation[0], whole.perturbation[0]);
        assert_eq!((h.donor, h.acceptor), (w.donor, w.acceptor));
        defect = defect.max((h.stabilization - 0.5 * w.stabilization).abs());
        defect = defect.max(
            (half.perturbation_total.unwrap() - 0.5 * whole.perturbation_total.unwrap()).abs(),
        );
    }
    println!("closed-shell spin channels against half the spin-summed analysis: {defect:.3e}");
    assert!(defect < 1e-10);

    let (cation, scf) = analyse(&WATER, "6-31g*", 1, 2, NboSpin::Auto);
    assert!(cation.open_shell);
    assert_eq!(cation.channels.len(), 2);
    let spin_sum: f64 = cation.nao.spin_populations.iter().sum();
    let (alpha, beta) = (&cation.channels[0], &cation.channels[1]);
    let alpha_lewis = lewis_labels(&cation, 0);
    let beta_lewis = lewis_labels(&cation, 1);
    let lone = |labels: &[String]| labels.iter().filter(|l| l.starts_with("LP")).count();
    println!(
        "water cation: spin populations {:?} (sum {spin_sum:.12}); alpha Lewis {alpha_lewis:?} \
         non-Lewis {:.6}; beta Lewis {beta_lewis:?} non-Lewis {:.6}",
        cation.nao.spin_populations, alpha.non_lewis_occupancy, beta.non_lewis_occupancy
    );
    assert!((spin_sum - 1.0).abs() < 1e-10);
    assert!((alpha.electrons - scf.n_alpha as f64).abs() < 1e-10);
    assert!((beta.electrons - scf.n_beta as f64).abs() < 1e-10);
    assert_eq!(alpha.lewis_count, scf.n_alpha);
    assert_eq!(beta.lewis_count, scf.n_beta);
    assert_eq!(lone(&alpha_lewis), lone(&beta_lewis) + 1);
}

#[test]
fn analysis_is_invariant_under_a_rotation() {
    let (c, s) = (0.6_f64, 0.8_f64);
    // Rotation by acos(0.6) about z, then by acos(0.6) about x.
    let rotate = |r: [f64; 3]| -> [f64; 3] {
        let (x, y, z) = (c * r[0] - s * r[1], s * r[0] + c * r[1], r[2]);
        [x, c * y - s * z, s * y + c * z]
    };
    let rotated: Vec<(u8, [f64; 3])> = FORMALDEHYDE.iter().map(|(z, r)| (*z, rotate(*r))).collect();
    let (a, _) = analyse(&FORMALDEHYDE, "6-31g*", 0, 1, NboSpin::Auto);
    let (b, _) = analyse(&rotated, "6-31g*", 0, 1, NboSpin::Auto);
    let mut defect = largest_difference(&a.nao.atomic_charges, &b.nao.atomic_charges);
    defect = defect.max(
        a.nao
            .wiberg_bond_indices
            .max_abs_diff(&b.nao.wiberg_bond_indices),
    );
    let (x, y) = (&a.channels[0], &b.channels[0]);
    for (p, q) in x.nbos.iter().zip(&y.nbos) {
        assert_eq!(p.label, q.label);
        let change = (p.occupancy - q.occupancy)
            .abs()
            .max((p.energy.unwrap() - q.energy.unwrap()).abs());
        if change > 1e-7 {
            println!(
                "  {}: occupancy {:.10} / {:.10}, energy {:.10} / {:.10}",
                p.label,
                p.occupancy,
                q.occupancy,
                p.energy.unwrap(),
                q.energy.unwrap()
            );
        }
        defect = defect.max(change);
    }
    for (p, q) in x.perturbation.iter().zip(&y.perturbation) {
        defect = defect.max((p.stabilization - q.stabilization).abs());
    }
    println!("rotated formaldehyde: largest change {defect:.3e}");
    assert!(defect < 1e-7);
}

#[test]
fn atomic_and_minimal_basis_limits() {
    let report = run(
        "natural-bond",
        &system(&[(10, [0.0; 3])]),
        &controls("6-31g*", 0, 1, &[]),
    )
    .unwrap();
    let configuration = report
        .get("natural_electron_configurations")
        .and_then(Value::as_array)
        .unwrap()[0]
        .as_str()
        .unwrap()
        .to_string();
    let channel = &report.get("channels").and_then(Value::as_array).unwrap()[0];
    let non_lewis = channel
        .get("non_lewis_occupancy")
        .and_then(Value::as_f64)
        .unwrap();
    let charge = floats(report.get("natural_charges").unwrap())[0];
    println!("neon: configuration {configuration}, charge {charge:.3e}, non-Lewis {non_lewis:.3e}");
    assert_eq!(configuration, "[core]2s(2.00)2p(6.00)");
    assert!(charge.abs() < 1e-10 && non_lewis.abs() < 1e-10);

    let report = run(
        "natural-bond",
        &system(&[(1, [0.0; 3]), (1, [0.0, 0.0, 1.4])]),
        &controls("sto-3g", 0, 1, &[]),
    )
    .unwrap();
    let wiberg = floats(report.get("wiberg_bond_indices").unwrap())[1];
    let channel = &report.get("channels").and_then(Value::as_array).unwrap()[0];
    let bond = &channel.get("nbos").and_then(Value::as_array).unwrap()[0];
    let occupancy = bond.get("occupancy").and_then(Value::as_f64).unwrap();
    println!("H2 minimal basis: Wiberg index {wiberg:.15}, bond occupancy {occupancy:.15}");
    assert_eq!(
        bond.get("label").and_then(Value::as_str),
        Some("BD(1) H1-H2")
    );
    assert!((wiberg - 1.0).abs() < 1e-12 && (occupancy - 2.0).abs() < 1e-12);
}
